        ws.cell(row=r, column=c).value = val

print("data dates:", [str(k) for k in data_map.keys()])
print("B2,C2:", ws["B2"].value, ws["C2"].value)
print("B12,C12:", ws["B12"].value, ws["C12"].value)

wb.save(OUT)
