        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y", "%Y/%m/%d"):
            try:
                return datetime.datetime.strptime(s, fmt).date()
            except ValueError:
                pass
        try:
            return datetime.datetime.strptime(s[:10], "%Y-%m-%d").date()
        except Exception:
            pass
    if isinstance(v, (int, float)):
        try:
            return (datetime.datetime(1899, 12, 30) + datetime.timedelta(days=float(v))).date()
        except Exception:
            return None
    return None

date_rows = []
for r in range(1, data_vals.max_row + 1):
    d = to_date(data_vals.cell(row=r, column=1).value)
