        if to_date(a) is not None:
            continue
        name = str(a).strip()
        if not name or name.lower() in {"agent name", "totals"}:
            continue
        val = data_vals.cell(row=r, column=6).value
        data_map.setdefault(d, {})[name] = val

ws = wb["Front"]

for c in (2, 3):
    d = to_date(front_vals.cell(row=1, column=c).value)
    for r in range(2, 13):
        agent = front_vals.cell(row=r, column=1).value
        if agent is None:
            out = None
        else:
            name = str(agent).strip()
            if d is None or d not in data_map:
                out = None
            else:
                out = data_map[d].get(name, None)

        if isinstance(out, str):
            out = out.strip()
            if out == "":
                out = None
            else:
                try:
                    out = float(out)
                except Exception:
                    pass

        ws.cell(row=r, column=c).value = out

print("data dates:", sorted(data_map.keys()))
print("B2,C2:", ws.cell(row=2, column=2).value, ws.cell(row=2, column=3).value)
print("B12,C12:", ws.cell(row=12, column=2).value, ws.cell(row=12, column=3).value)

wb.save(OUT)
